// C++ Standard Practice: Never throw from a destructor (C.37)
class FileHandle {
    FILE* fp;
public:
    // Destructor must internally handle closing errors
    ~FileHandle() {
        if (fp) {
            // Using non-throwing internal logic (e.g., C APIs)
            if (fclose(fp) != 0) {
                // Log or swallow error; DO NOT throw.
                std::cerr << "Error closing file." << std::endl;
            }
        }
    }
};

